import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 3 Matterhorn man","description":"学习 used to、would 与过去状态，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 3 Matterhorn man","description":"学习 used to、would 与过去状态，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 used to、would 与过去状态，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 2 Spare that spider","link":"/life/english/new-concept/book-4/unit-01/lesson-002"},"next":{"text":"第四册：流利英语 · Lesson 4 Seeing hands","link":"/life/english/new-concept/book-4/unit-01/lesson-004"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 2 Spare that spider","link":"/life/english/new-concept/book-4/unit-01/lesson-002"},"next":{"text":"第四册：流利英语 · Lesson 4 Seeing hands","link":"/life/english/new-concept/book-4/unit-01/lesson-004"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-003.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-003.md"}'),i={name:"life/english/new-concept/book-4/unit-01/lesson-003.md"};function l(s,e,r,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-3-matterhorn-man" tabindex="-1">第四册：流利英语 · Lesson 3 Matterhorn man <a class="header-anchor" href="#第四册-流利英语-·-lesson-3-matterhorn-man" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 3 Matterhorn man&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从山区向导、登山活动与外来游客的接触切入，学习区分过去习惯、一次事件和后来的变化。关注叙事者如何组织地方生活与社会转变，避免把某一时期的山区居民概括成永久不变的群体。用清楚的时间界限讲述一种职业的改变。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>guide</td><td>/ɡaɪd/</td><td>n.</td><td>向导</td><td>a mountain guide</td></tr><tr><td>slope</td><td>/sləʊp/</td><td>n.</td><td>斜坡</td><td>a steep slope</td></tr><tr><td>summit</td><td>/ˈsʌmɪt/</td><td>n.</td><td>山顶</td><td>reach the summit</td></tr><tr><td>livelihood</td><td>/ˈlaɪvlihʊd/</td><td>n.</td><td>生计</td><td>earn a livelihood</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make a living — 谋生</li><li>set out — 出发，常与时间或目的搭配</li></ul><h2 id="语法讲解-used-to、would-与过去状态" tabindex="-1">语法讲解：used to、would 与过去状态 <a class="header-anchor" href="#语法讲解-used-to、would-与过去状态" aria-label="Permalink to &quot;语法讲解：used to、would 与过去状态&quot;">​</a></h2><p>used to 可以描述过去的习惯，也可以描述如今不再成立的状态；would 叙述过去反复发生的动作时，需要已建立的过去时间背景。描述过去住在哪里等静态情况，通常用 used to live，而不是单独用 would live。一次特定登山经历用一般过去时。否定形式 did not use to 中 use 不加 d，疑问句同样由 did 承担过去时标记。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The village used to be quiet, but each summer guides would welcome new climbers.</p></blockquote><p>村庄过去很安静，但每年夏天向导们都会迎接新的登山者。</p><p>used to be 表过去状态；each summer 为 would welcome 建立反复行为的时间框架。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要用 would be quiet 无背景地替代 used to be quiet；would 还可能被理解为条件结果。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把三句中的 used to、would、today 分别圈出再朗读；录音检查过去与现在的时间转折是否清楚。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The village used to depend on farming. In summer, some residents would guide visitors along the ridge. Today, tourism provides another source of income.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句介绍一个山村职业变化：过去状态、每年的习惯、现在的变化。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>状态用 used to，习惯用有时间背景的 would，现在用 today 切换时态。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Did the guide ___ to work alone?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> use</p><p><strong>解析：</strong> did 后接原形 use。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>“昨天他到达山顶”应使用 reached 还是 used to reach？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> reached</p><p><strong>解析：</strong> yesterday 指一次特定事件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例中哪个短语表示周期性重复？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> each summer</p><p><strong>解析：</strong> 它说明 welcome 是反复发生的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：used to、would 与过去状态。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-004">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
